<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue';
import { Plus, Refresh, Search } from '@element-plus/icons-vue';
import { apiRequest } from '../../lib/api.js';
const rows=ref([]),templates=ref([]),accounts=ref([]),search=ref(''),open=ref(false),error=ref(''),notice=ref(''),loading=ref(false),saving=ref(false);
const form=reactive({name:'',template:'',limit:'',enabled:true,note:'',trigger:'followed',account:'',delay:0,schedule:'daily',timezone:'Asia/Shanghai',hour:9,minute:0,cron:'',conditions:[]});
const filtered=computed(()=>rows.value.filter(row=>row.name.includes(search.value.trim()))), templateNames=computed(()=>Object.fromEntries(templates.value.map(row=>[row.id,row.name]))), accountNames=computed(()=>Object.fromEntries(accounts.value.map(row=>[row.id,row.nickname||row.name])));
const cron=computed(()=>form.schedule==='daily'?`${form.minute} ${form.hour} * * *`:form.schedule==='weekly'?`${form.minute} ${form.hour} * * 1`:form.cron||'—');
function reset(){Object.assign(form,{name:'',template:'',limit:'',enabled:true,note:'',trigger:'followed',account:'',delay:0,schedule:'daily',timezone:'Asia/Shanghai',hour:9,minute:0,cron:'',conditions:[]});error.value='';open.value=true}
async function load(){loading.value=true;try{[rows.value,templates.value,accounts.value]=await Promise.all([apiRequest('automations'),apiRequest('task-templates'),apiRequest('accounts')])}catch(cause){notice.value=cause.message;rows.value=[];templates.value=[];accounts.value=[]}finally{loading.value=false}}
function triggerConfig(){if(form.trigger==='followed')return{account:form.account,delay:Number(form.delay),conditions:form.conditions};if(form.trigger==='schedule')return{schedule:form.schedule,timezone:form.timezone,hour:Number(form.hour),minute:Number(form.minute),cron:form.cron};return{}}
async function save(){if(!form.name.trim()||!form.template){error.value='请填写任务名称并选择任务模板。';return}if(form.trigger!=='followed'){error.value='手动触发和定时触发暂未接入，请选择被关注后触发。';return}if(!form.account){error.value='被关注后触发时必须选择触发账号。';return}const dailyLimit=form.trigger==='manual'||form.limit===''?null:Number(form.limit);if(dailyLimit!==null&&(!Number.isInteger(dailyLimit)||dailyLimit<1)){error.value='每日触发上限必须是正整数或留空。';return}saving.value=true;error.value='';try{await apiRequest('automations',{method:'POST',body:{name:form.name,template:form.template,enabled:form.enabled,note:form.note,triggerType:form.trigger,dailyLimit,triggerConfig:triggerConfig()}});open.value=false;await load();notice.value='任务已创建。'}catch(cause){error.value=cause.message}finally{saving.value=false}}
async function toggle(row){try{await apiRequest(`automations/${row.id}`,{method:'PATCH',body:{enabled:row.enabled}})}catch(cause){row.enabled=!row.enabled;notice.value=cause.message}}
async function remove(row){try{await apiRequest(`automations/${row.id}`,{method:'DELETE'});await load();notice.value='任务已删除。'}catch(cause){notice.value=cause.message}}
function triggerLabel(row){if(row.trigger_type==='manual')return'手动触发';if(row.trigger_type==='followed')return`被关注后触发 · ${accountNames.value[row.trigger_config.account]||'账号已删除'}`;const config=row.trigger_config;return config.schedule==='cron'?config.cron:config.schedule==='weekly'?`${config.minute} ${config.hour} * * 1`:`${config.minute} ${config.hour} * * *`}
onMounted(()=>{window.addEventListener('douyinjuhe-session',load);load()});onUnmounted(()=>window.removeEventListener('douyinjuhe-session',load));
</script>
<template><section><div class="toolbar"><el-input v-model="search" :prefix-icon="Search" placeholder="搜索任务名称" clearable/><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button><el-button type="primary" :icon="Plus" :disabled="!templates.length" @click="reset">新增任务</el-button></div><div class="panel"><el-alert v-if="notice" :title="notice" type="info" show-icon @close="notice=''"/><el-alert v-if="!loading&&!templates.length" title="请先创建至少一个任务模板。" type="warning" show-icon :closable="false"/><el-table v-loading="loading" :data="filtered" empty-text="暂无任务"><el-table-column prop="name" label="任务名称" min-width="140"/><el-table-column label="引用模板" min-width="140"><template #default="{row}">{{templateNames[row.template]||'模板已删除'}}</template></el-table-column><el-table-column label="执行账号" min-width="120"><template #default="{row}">{{row.trigger_type==='followed'?(accountNames[row.trigger_config.account]||'账号已删除'):'—'}}</template></el-table-column><el-table-column label="每日触发上限" width="120"><template #default="{row}">{{row.daily_limit||'不限'}}</template></el-table-column><el-table-column label="触发方式" min-width="150"><template #default="{row}">{{triggerLabel(row)}}</template></el-table-column><el-table-column label="启用" width="80"><template #default="{row}"><el-switch v-model="row.enabled" @change="toggle(row)"/></template></el-table-column><el-table-column label="来源" width="100"><template #default>手动创建</template></el-table-column><el-table-column label="更新时间" width="170"><template #default="{row}">{{new Date(row.updated).toLocaleString()}}</template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}"><el-popconfirm title="确定删除这个任务？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></div>
<el-dialog v-model="open" title="新增任务" width="min(820px,96vw)"><el-form label-position="top"><h3>基础信息</h3><div class="grid"><el-form-item label="任务名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="引用模板" required><el-select v-model="form.template" placeholder="请选择任务模板"><el-option v-for="item in templates" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item v-if="form.trigger!=='manual'" label="每日触发上限"><el-input v-model="form.limit" inputmode="numeric"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled" active-text="启用"/></el-form-item></div><el-form-item label="备注"><el-input v-model="form.note" type="textarea" maxlength="255" show-word-limit/></el-form-item><h3>触发配置</h3><el-form-item label="触发方式"><el-select v-model="form.trigger"><el-option label="手动触发（暂未接入）" value="manual" disabled/><el-option label="被关注后触发" value="followed"/><el-option label="定时触发（暂未接入）" value="schedule" disabled/></el-select></el-form-item><template v-if="form.trigger==='followed'"><el-form-item label="触发账号" required><el-select v-model="form.account" placeholder="请选择触发账号"><el-option v-for="item in accounts" :key="item.id" :label="item.nickname||item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="延时执行"><el-input-number v-model="form.delay" :min="0"/> 秒</el-form-item><small>该账号每次被新用户关注都会触发。</small></template><template v-else-if="form.trigger==='schedule'"><div class="grid"><el-form-item label="定时类型"><el-select v-model="form.schedule"><el-option label="每天" value="daily"/><el-option label="每周" value="weekly"/><el-option label="自定义 Cron" value="cron"/></el-select></el-form-item><el-form-item label="时区"><el-input v-model="form.timezone"/></el-form-item><el-form-item v-if="form.schedule!=='cron'" label="小时"><el-input-number v-model="form.hour" :min="0" :max="23"/></el-form-item><el-form-item v-if="form.schedule!=='cron'" label="分钟"><el-input-number v-model="form.minute" :min="0" :max="59"/></el-form-item><el-form-item v-else label="Cron"><el-input v-model="form.cron"/></el-form-item></div><p>当前生成的 Cron：{{cron}}</p></template><p v-else>当前任务为手动触发，不会自动执行。</p><aside class="preview"><strong>触发与执行预览</strong><p>{{form.trigger==='manual'?'手动触发':form.trigger==='followed'?`被关注后触发 · 账号：${accountNames[form.account]||'--'} · 延时 ${form.delay} 秒`:`定时触发 · ${cron} · ${form.timezone}`}}</p><span>{{form.template?`执行模板：${templateNames[form.template]}`:'选择模板后显示执行步骤'}}</span></aside></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">创建任务</el-button></template></el-dialog></section></template>
<style scoped>.toolbar{display:flex;justify-content:flex-end;gap:10px;margin-bottom:22px;flex-wrap:wrap}.toolbar .el-input{width:280px}.panel{background:#fff;border-radius:20px;padding:20px;min-height:calc(100vh - 235px)}.panel .el-alert{margin-bottom:14px}.panel :deep(.el-table__empty-block){min-height:390px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.el-select{width:100%}.preview{background:#f4f8fe;border:1px solid #e3ebf7;border-radius:8px;padding:14px;margin-top:16px}.preview p{color:#52657e}.preview span,small{display:block;color:#8996a9;margin-top:10px}@media(max-width:650px){.toolbar .el-input{width:100%}.panel{padding:12px}.grid{grid-template-columns:1fr}}</style>
